  status TEXT DEFAULT 'available' CHECK(status IN
    ('available','requested','pickup_pending','picked_up','overdue','damaged','maintenance','retired','lost')),
  location TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP,
