def _now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


def _json(value: Any) -> str:
    return json.dumps({} if value is None else value, separators=(",", ":"))


def _row(row: sqlite3.Row | None) -> dict[str, Any] | None:
    return dict(row) if row is not None else None


def _rows(rows: Iterable[sqlite3.Row]) -> list[dict[str, Any]]:
    return [dict(row) for row in rows]


def _one(value: Any) -> Any:
    return value[0] if isinstance(value, dict) and len(value) == 1 else value


class Database:
    """Database facade. Create one instance per backend process or database path."""

    def __init__(self, path: str | os.PathLike[str] | None = None):
        self.path = Path(path or DB_PATH)
        self.connection = sqlite3.connect(self.path)
        self.connection.row_factory = sqlite3.Row
        self.connection.execute("PRAGMA foreign_keys = ON")
        self.connection.execute("PRAGMA journal_mode = WAL")
        self.connection.executescript(SCHEMA)
        for statement in (
            "ALTER TABLE users ADD COLUMN pin_hash TEXT DEFAULT ''",
            "ALTER TABLE users ADD COLUMN failed_pin_attempts INTEGER DEFAULT 0",
            "ALTER TABLE users ADD COLUMN locked_until TEXT",
        ):
            try:
                self.connection.execute(statement)
            except sqlite3.OperationalError as error:
                if "duplicate column name" not in str(error).lower():
                    raise
        listing_columns = {row[1] for row in self.connection.execute("PRAGMA table_info(listings)")}
        if "images" not in listing_columns:
            self.connection.execute("ALTER TABLE listings ADD COLUMN images TEXT NOT NULL DEFAULT '[]'")
        equipment_columns = {row[1] for row in self.connection.execute("PRAGMA table_info(equipment)")}
        if "listing_id" not in equipment_columns:
            self.connection.execute("ALTER TABLE equipment ADD COLUMN listing_id INTEGER REFERENCES listings(id)")
        self.connection.execute("CREATE INDEX IF NOT EXISTS idx_equipment_listing ON equipment(listing_id)")
        self.connection.execute("UPDATE users SET role='student' WHERE role='lendee' OR role IS NULL OR role='' ")
        self.connection.commit()

    @contextmanager
    def _transaction(self):
        try:
            yield
            self.connection.commit()
        except Exception:
            self.connection.rollback()
            raise

    def _audit(self, actor: int | None, entity_type: str, entity_id: int, action: str, details: Any = None):
        self.connection.execute(
            "INSERT INTO audit_log(actor_id,entity_type,entity_id,action,details) VALUES (?,?,?,?,?)",
            (actor or None, entity_type, entity_id, action, _json(details)),
        )

    def _emit(self, event_type: str, aggregate_type: str, aggregate_id: int, payload: Any = None):
        self.connection.execute(
            "INSERT INTO outbox_events(event_type,aggregate_type,aggregate_id,payload) VALUES (?,?,?,?)",
            (event_type, aggregate_type, aggregate_id, _json(payload)),
        )

    def add_user(self, data: dict[str, Any]) -> dict[str, Any]:
        if not data.get("kreaId") or not data.get("name"):
            raise ValueError("kreaId and name are required")
        cur = self.connection.execute(
            "INSERT INTO users(krea_id,name,email,department,role,notification_preferences) VALUES (?,?,?,?,?,?)",
            (data["kreaId"], data["name"], data.get("email"), data.get("department", ""),
             data.get("role", "student"), _json(data.get("notificationPreferences"))),
        )
        self.connection.commit()
        return _row(self.connection.execute("SELECT * FROM users WHERE id=?", (cur.lastrowid,)).fetchone())

    def list_users(self):
        return _rows(self.connection.execute(
            "SELECT id,krea_id,name,email,department,role,banned,created_at FROM users ORDER BY name COLLATE NOCASE"
        ))

    def update_user(self, user_id: int, data: dict[str, Any], commit: bool = True) -> dict[str, Any] | None:
        fields = {"kreaId": "krea_id", "name": "name", "email": "email", "department": "department",
                  "role": "role", "banned": "banned", "banReason": "ban_reason"}
        updates = [(column, data[key]) for key, column in fields.items() if key in data]
        if updates:
            assignments = ",".join(f"{column}=?" for column, _ in updates)
            self.connection.execute(f"UPDATE users SET {assignments},updated_at=? WHERE id=?",
                                    [value for _, value in updates] + [_now(), user_id])
            if commit:
                self.connection.commit()
        return _row(self.connection.execute("SELECT * FROM users WHERE id=?", (user_id,)).fetchone())

    def ban_user(self, user_id: int, reason: str = "", actor_id: int | None = None):
        with self._transaction():
            self.update_user(user_id, {"banned": 1, "banReason": reason}, commit=False)
            self.connection.execute("INSERT INTO ban_history(user_id,action,reason,actor_id) VALUES (?,?,?,?)",
                                    (user_id, "banned", reason, actor_id))
            self._audit(actor_id, "user", user_id, "banned", {"reason": reason})
            self._emit("user.banned", "user", user_id, {"reason": reason})
        return self.update_user(user_id, {})

    def unban_user(self, user_id: int, actor_id: int | None = None):
        with self._transaction():
            self.update_user(user_id, {"banned": 0, "banReason": ""}, commit=False)
            self.connection.execute("INSERT INTO ban_history(user_id,action,actor_id) VALUES (?,?,?)",
                                    (user_id, "unbanned", actor_id))
            self._audit(actor_id, "user", user_id, "unbanned")
            self._emit("user.unbanned", "user", user_id)
        return self.update_user(user_id, {})

    def add_listing(self, data: dict[str, Any]) -> dict[str, Any]:
        if not data.get("listingCode") or not data.get("name"):
            raise ValueError("listingCode and name are required")
        cur = self.connection.execute(
            "INSERT INTO listings(listing_code,name,description,category,location,quantity,images) VALUES (?,?,?,?,?,?,?)",
            (data["listingCode"], data["name"], data.get("description", ""), data.get("category", ""),
             data.get("location", ""), int(data.get("quantity", 0)), _json(data.get("images", []))),
        )
        self.connection.commit()
        result = _row(self.connection.execute("SELECT * FROM listings WHERE id=?", (cur.lastrowid,)).fetchone())
        decoded_images = json.loads(result.get("images") or "[]")
        result["images"] = decoded_images if isinstance(decoded_images, list) else []
        return result

    def get_listings(self, filters=None):
        filters = filters or {}
        clauses, params = [], []
        if filters.get("q"):
            clauses.append("(l.name LIKE ? OR l.listing_code LIKE ? OR l.description LIKE ? OR l.category LIKE ?)")
            params.extend([f"%{filters['q']}%"] * 4)
        where = " WHERE " + " AND ".join(clauses) if clauses else ""
        rows = self.connection.execute(f"""SELECT l.*,
            COUNT(e.id) AS equipment_quantity,
            COALESCE(SUM(CASE WHEN e.status='available' THEN 1 ELSE 0 END), 0) AS available_quantity,
            COALESCE(SUM(CASE WHEN e.status IN ('picked_up','overdue') THEN 1 ELSE 0 END), 0) AS checked_out_quantity,
            COALESCE(SUM(CASE WHEN e.status='lost' THEN 1 ELSE 0 END), 0) AS lost_quantity,
            COALESCE(SUM(CASE WHEN e.status='damaged' THEN 1 ELSE 0 END), 0) AS damaged_quantity,
            GROUP_CONCAT(e.id) AS equipment_ids,
            GROUP_CONCAT(CASE WHEN e.status='available' THEN e.id END) AS available_equipment_ids
            FROM listings l LEFT JOIN equipment e ON e.listing_id=l.id{where}
            GROUP BY l.id ORDER BY l.name COLLATE NOCASE""", params).fetchall()
        result = []
        for row in rows:
